from __future__ import annotations

import csv
import json
import re
from collections import defaultdict
from datetime import date, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from pathlib import Path


DATASET = Path("/app/dataset")


def _read_csv(name: str) -> list[dict[str, str]]:
    with (DATASET / name).open(encoding="utf-8", newline="") as file:
        return list(csv.DictReader(file))


def _previous_month(year: int, month: int) -> tuple[int, int]:
    return (year - 1, 12) if month == 1 else (year, month - 1)


def _billing_month(work_date: date, billing_weekday: int) -> tuple[int, int]:
    """Return the month whose first billing-weekday starts this period."""
    month_start = work_date.replace(day=1)
    offset = (billing_weekday - month_start.weekday()) % 7
    period_start = month_start + timedelta(days=offset)
    if work_date < period_start:
        return _previous_month(work_date.year, work_date.month)
    return work_date.year, work_date.month


def answer() -> dict[str, list[int]]:
    employee_rows = _read_csv("employees.csv")
    task_rows = _read_csv("tasks.csv")
    timesheet_rows = _read_csv("timesheet.csv")

    # The employee and task master files define the valid identifiers and rates.
    rates: dict[str, Decimal] = {}
    for row in employee_rows:
        try:
            pesel = row["PESEL"].strip()
            rate = Decimal(row["hourly_rate"])
        except (KeyError, InvalidOperation):
            continue
        if re.fullmatch(r"\d{11}", pesel) and rate >= 0:
            rates[pesel] = rate

    task_pay: dict[int, Decimal] = {}
    for row in task_rows:
        try:
            task_id = int(row["task_id"])
            pay = Decimal(row["pay_per_completion"])
        except (KeyError, ValueError, InvalidOperation):
            continue
        if pay >= 0:
            task_pay[task_id] = pay

    # IDs are row identifiers only. Several otherwise identical rows have a
    # different ID, so compare every substantive field when removing copies.
    substantive_fields = tuple(
        field for field in timesheet_rows[0] if field != "id"
    ) if timesheet_rows else ()
    seen: set[tuple[str, ...]] = set()
    cleaned: list[tuple[str, date, Decimal, Decimal]] = []

    for row in timesheet_rows:
        signature = tuple(row.get(field, "") for field in substantive_fields)
        if signature in seen:
            continue
        seen.add(signature)

        pesel = row.get("employee_id", "").strip()
        if pesel not in rates:
            # These rows cannot be assigned safely: the valid employee already
            # has a separate, complete timesheet stream for the same periods.
            continue

        try:
            work_date = date.fromisoformat(row["date"].strip())
            hours = Decimal(row["hours_worked"])
        except (KeyError, ValueError, InvalidOperation):
            # In particular, April 31 and June 31 have no defensible exact date.
            continue
        if not hours.is_finite() or hours < 0 or hours > 24:
            continue

        # Missing list brackets are recoverable. Unknown task numbers are not;
        # retain the valid completions and omit only the unknown bonuses.
        task_ids = (int(value) for value in re.findall(r"\d+", row.get("performed_tasks", "")))
        bonus = sum((task_pay[task_id] for task_id in task_ids if task_id in task_pay), Decimal(0))
        cleaned.append((pesel, work_date, hours, bonus))

    if not cleaned:
        return {pesel: [] for pesel in rates}

    billing_weekday = min(record[1] for record in cleaned).weekday()
    totals: defaultdict[tuple[str, tuple[int, int]], Decimal] = defaultdict(Decimal)
    billing_months: set[tuple[int, int]] = set()

    for pesel, work_date, hours, bonus in cleaned:
        month = _billing_month(work_date, billing_weekday)
        billing_months.add(month)
        totals[(pesel, month)] += hours * rates[pesel] + bonus

    ordered_months = sorted(billing_months)
    result: dict[str, list[int]] = {}
    for pesel in rates:
        result[pesel] = [
            int(totals[(pesel, month)].quantize(Decimal("1"), rounding=ROUND_HALF_UP))
            for month in ordered_months
        ]
    return result


if __name__ == "__main__":
    with Path("/app/answer.json").open("w", encoding="utf-8") as file:
        json.dump(answer(), file, default=list)

